insert into sector_profiles (settore, version, status, pack, changelog)
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Cos''è il salvavita?', $qktcd1u$["cosa e il salvavita","che cos e il salvavita","a cosa serve il salvavita","come funziona il salvavita","cos e un differenziale","cos e l interruttore differenziale"]$qktcd1u$::jsonb, 'Salvavita è il nome comune dell''interruttore differenziale: interrompe automaticamente la corrente quando rileva una dispersione verso terra, per proteggere le persone dal rischio di scosse e l''impianto dai danni.', $qs8qjb4${}$qs8qjb4$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Perché scatta il salvavita?', $qoxmuhe$["perche salta il salvavita","come mai scatta il salvavita","perche mi scatta il salvavita","come mai salta il salvavita","perche scatta il differenziale"]$qoxmuhe$::jsonb, 'Il salvavita scatta quando rileva una dispersione di corrente: le cause possono essere diverse, per esempio un apparecchio difettoso, umidità o un cavo danneggiato. Non si può capire a distanza: se scatta spesso o non si riarma, conviene far controllare l''impianto da un elettricista senza forzarlo.', $q20rauh${}$q20rauh$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Che differenza c''è tra salvavita e magnetotermico?', $qgadoos$["differenza tra salvavita e magnetotermico","differenza tra differenziale e magnetotermico","salvavita e magnetotermico sono la stessa cosa","magnetotermico o differenziale"]$qgadoos$::jsonb, 'Il differenziale (salvavita) protegge le persone dalle dispersioni di corrente; il magnetotermico protegge cavi e impianto da sovraccarichi e cortocircuiti. Nel quadro spesso ci sono entrambi, a volte combinati in un unico dispositivo.', $ql98yrp${}$ql98yrp$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Cos''è il magnetotermico?', $q63xemx$["cosa e il magnetotermico","a cosa serve il magnetotermico","come funziona il magnetotermico","perche salta il magnetotermico"]$q63xemx$::jsonb, 'Il magnetotermico è l''interruttore che interviene quando passa troppa corrente in un circuito (sovraccarico) o in caso di cortocircuito. Se interviene spesso è un segnale che l''impianto va verificato da un professionista.', $qcuq4yk${}$qcuq4yk$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Cos''è il quadro elettrico?', $qjz465f$["cosa e il quadro elettrico","a cosa serve il quadro elettrico","che cos e il quadro elettrico","cos e il centralino"]$qjz465f$::jsonb, 'Il quadro elettrico (o centralino) è il punto dell''impianto dove sono raccolti gli interruttori di protezione che distribuiscono e proteggono la corrente nei vari circuiti della casa o dell''attività.', $qv64u9g${}$qv64u9g$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Cosa significa impianto a norma?', $qxtpg31$["cosa vuol dire impianto a norma","cos e un impianto a norma","quando un impianto e a norma","cosa significa che l impianto e a norma","cosa vuol dire a norma"]$qxtpg31$::jsonb, 'Un impianto è a norma quando è realizzato e mantenuto secondo le norme tecniche e di legge, con componenti adeguati, protezioni (come differenziale e messa a terra) e la documentazione prevista. La verifica spetta a un tecnico abilitato.', $qpm1m3l${}$qpm1m3l$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Cos''è la dichiarazione di conformità?', $quu38df$["cosa e la dichiarazione di conformita","cos e la di co","a cosa serve la dichiarazione di conformita","cosa significa dichiarazione di conformita","cos e il certificato dell impianto"]$quu38df$::jsonb, 'La dichiarazione di conformità è il documento che l''impresa installatrice abilitata rilascia al termine dei lavori per attestare che l''impianto è stato realizzato a regola d''arte. Se serve nel suo caso lo valuta l''impresa.', $qtw8l43${}$qtw8l43$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Cos''è la messa a terra?', $qf0db5i$["cosa e la messa a terra","a cosa serve la messa a terra","che cos e l impianto di terra","cosa significa messa a terra"]$qf0db5i$::jsonb, 'La messa a terra è il collegamento che convoglia verso terra le correnti disperse, in modo che non passino attraverso le persone. Insieme al differenziale è una delle protezioni fondamentali dell''impianto.', $qnqzcyw${}$qnqzcyw$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Serve la certificazione dell''impianto per vendere o affittare casa?', $q0n3fii$["serve la certificazione per vendere casa","serve la dichiarazione di conformita per l affitto","per vendere casa serve il certificato dell impianto","certificato impianto per la compravendita"]$q0n3fii$::jsonb, 'In molti casi può essere richiesta documentazione sull''impianto, ma dipende dalla situazione. Per il suo caso specifico conviene confrontarsi con chi segue la compravendita o l''affitto e con l''impresa elettrica.', $qypanlo${}$qypanlo$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Ogni quanto va controllato l''impianto elettrico?', $q3ostp7$["ogni quanto va verificato l impianto","ogni quanto si controlla l impianto elettrico","quando fare la verifica dell impianto","va controllato periodicamente l impianto"]$q3ostp7$::jsonb, 'Non c''è un''unica regola valida per tutti: è buona pratica una verifica periodica, soprattutto su impianti datati e dopo modifiche o episodi anomali. L''elettricista può indicare la cadenza più adatta.', $qire9j0${}$qire9j0$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Quali segnali indicano che l''impianto va controllato?', $qd0awvu$["quando chiamare l elettricista","segnali di impianto da controllare","come capisco se l impianto e vecchio","quando devo far controllare l impianto"]$qd0awvu$::jsonb, 'Segnali tipici sono salvavita che scatta spesso, prese o spine che scaldano, luci che sfarfallano, impianto molto datato o privo di protezioni. In questi casi è meglio far verificare l''impianto a un elettricista.', $q68n6cy${}$q68n6cy$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Cos''è una wallbox?', $qyt9xnk$["cosa e una wallbox","a cosa serve la wallbox","cos e la colonnina di ricarica","come funziona la wallbox","cos e un punto di ricarica"]$qyt9xnk$::jsonb, 'La wallbox è un dispositivo fissato a parete per ricaricare l''auto elettrica a casa in modo sicuro. L''installazione richiede una verifica dell''impianto e della potenza disponibile.', $qh55b11${}$qh55b11$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Come funziona un impianto fotovoltaico?', $q0nsj34$["cos e un impianto fotovoltaico","come funziona il fotovoltaico","cosa e il fotovoltaico","come funzionano i pannelli fotovoltaici"]$q0nsj34$::jsonb, 'L''impianto fotovoltaico trasforma la luce del sole in elettricità: l''energia prodotta si usa in casa e può essere accumulata in una batteria o immessa in rete. Il dimensionamento dipende da consumi e spazio disponibile, quindi serve un sopralluogo.', $qdxglf8${}$qdxglf8$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Cos''è la potenza impegnata?', $qv8cofx$["cosa e la potenza impegnata","cosa significa potenza impegnata","cosa vuol dire potenza del contatore","perche il contatore scatta con troppi apparecchi","cos e la potenza del contatore"]$qv8cofx$::jsonb, 'La potenza impegnata è il massimo che si può usare contemporaneamente: se si supera, il contatore può interrompere la corrente. Un aumento si richiede al fornitore di energia; un elettricista può verificare l''impianto.', $qo227d3${}$qo227d3$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Posso fare da solo i lavori sull''impianto elettrico?', $qtf1myq$["posso sostituire una presa da solo","si possono fare lavori elettrici da soli","posso fare l impianto da solo","lavori elettrici fai da te"]$qtf1myq$::jsonb, 'I lavori sull''impianto elettrico vanno affidati a professionisti abilitati: errori possono causare rischi per le persone e per l''immobile, e per alcuni interventi è prevista la dichiarazione di conformità.', $qjud1lh${}$qjud1lh$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Cos''è il sopralluogo e perché serve?', $qaoyx4t$["a cosa serve il sopralluogo","in cosa consiste il sopralluogo","cosa si fa durante il sopralluogo","perche serve il sopralluogo"]$qaoyx4t$::jsonb, 'Il sopralluogo è una visita sul posto per vedere impianto, spazi ed esigenze: in molti lavori serve per fare un preventivo preciso. Modalità e condizioni dipendono dall''impresa.', $qa878pu${}$qa878pu$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_documenti', 'Cosa serve per avere un preventivo?', $qgk725y$["cosa devo preparare per il preventivo","cosa serve per un preventivo preciso","quali informazioni servono per il preventivo","cosa vi serve per fare il preventivo"]$qgk725y$::jsonb, 'Per un preventivo sono utili una descrizione dei lavori, il tipo di immobile, foto del quadro elettrico e delle zone interessate e, se disponibile, la planimetria. Per i dettagli verifichi con l''impresa.', $q7ymayq${}$q7ymayq$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Perché le luci sfarfallano?', $qfugzq1$["perche le luci lampeggiano","come mai la luce sfarfalla","luci che sfarfallano perche"]$qfugzq1$::jsonb, 'Le luci che sfarfallano possono avere cause diverse (lampadina, alimentatore, regolatore di luce, contatti allentati): a distanza non si può stabilire. Se succede spesso o insieme ad altri segnali, conviene far controllare l''impianto.', $q9wgogp${}$q9wgogp$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Il climatizzatore ha bisogno di una linea dedicata?', $qj5qxru$["serve una linea dedicata per il condizionatore","il condizionatore ha bisogno di una linea elettrica dedicata","linea dedicata per il climatizzatore"]$qj5qxru$::jsonb, 'Spesso è consigliata una linea dedicata e protetta per il climatizzatore, ma dipende dall''impianto esistente: la verifica si fa in sopralluogo.', $q1ff546${}$q1ff546$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Ogni quanto va fatta la manutenzione del cancello automatico?', $qiut6n1$["il cancello automatico va controllato","manutenzione del cancello elettrico","ogni quanto controllare l automazione del cancello"]$qiut6n1$::jsonb, 'Per sicurezza e buon funzionamento è consigliata una manutenzione periodica dell''automazione del cancello da parte di un tecnico; la frequenza la indica l''installatore.', $q2iiqn1${}$q2iiqn1$::jsonb);
insert into sector_faq (settore, version, status, intent, domanda_canonica, varianti, risposta_base, condizioni) values ('elettricista', 1, 'production', 'info_tecniche', 'Cos''è la domotica?', $q6vb7ms$["cosa e la domotica","cosa significa domotica","cos e una casa intelligente","che cos e la domotica"]$q6vb7ms$::jsonb, 'La domotica è l''insieme di dispositivi e automazioni (luci, tapparelle, clima, allarme) controllabili in modo coordinato, anche da smartphone. Cosa è possibile dipende dall''impianto e dalle esigenze.', $q1e0dxm${}$q1e0dxm$::jsonb);
insert into sector_eval_runs (profile_id, settore, version, scenari_totali, scenari_passati, metriche, gate_passed, note)
